     border-radius: 999px;
     font-size: 12px;
     font-weight: 500;
   }

   /* ── DEMO STEPS ── */
   .steps {
     list-style: none;
     display: flex;
     flex-direction: column;
     gap: 0;
   }
   .step {
     display: flex;
     gap: 16px;
     position: relative;
   }
   .step::before {
     content: '';
     position: absolute;
     left: 19px;
     top: 40px;
     bottom: -8px;
     width: 2px;
     background: var(--border);
   }
   .step:last-child::before { display: none; }
   .step-num {
     width: 38px;
     height: 38px;
     min-width: 38px;
     background: rgba(91,106,245,0.15);
     border: 1px solid rgba(91,106,245,0.35);
     border-radius: 50%;
     display: flex;
     align-items: center;
     justify-content: center;
     font-size: 13px;
     font-weight: 700;
     color: #a5b4fc;
     z-index: 1;
   }
   .step-body {
     padding: 8px 0 24px;
   }
   .step-title {
     font-size: 14px;
     font-weight: 600;
     color: var(--text);
     margin-bottom: 4px;
   }
   .step-desc {
     font-size: 13px;
     color: var(--muted);
   }
   .step-code {
     display: inline-block;
     background: rgba(0,0,0,0.4);
     border: 1px solid var(--border);
     border-radius: 6px;
     padding: 2px 8px;
     font-family: 'Courier New', monospace;
     font-size: 12px;
     color: #93c5fd;
     margin-top: 4px;
   }

   /* ── DECISION TABLE ── */
   .decision-card {
     background: var(--card);
     border: 1px solid var(--border);
