     gap: 12px;
     padding: 10px 18px;
     font-size: 11px;
     color: var(--muted);
     text-transform: uppercase;
     letter-spacing: 1px;
     background: var(--surface);
     border-bottom: 1px solid var(--border);
   }
   .risk-wrap {
     background: var(--card);
     border: 1px solid var(--border);
     border-radius: 12px;
     overflow: hidden;
   }

   /* ── TIMELINE ── */
   .timeline {
     position: relative;
     padding-left: 32px;
   }
   .timeline::before {
     content: '';
     position: absolute;
     left: 7px;
     top: 8px;
     bottom: 0;
     width: 2px;
     background: var(--border);
