     font-size: 11px;
     color: var(--muted);
     margin-bottom: 8px;
   }
   .module-icons {
     display: flex;
     gap: 6px;
     flex-wrap: wrap;
   }

   /* ── NAVBAR (print nav hidden) ── */
   .nav {
     position: sticky;
     top: 0;
     z-index: 100;
     background: rgba(15,17,23,0.92);
     backdrop-filter: blur(12px);
     border-bottom: 1px solid var(--border);
