   .nav-logo {
     font-size: 13px;
     font-weight: 700;
     color: #a5b4fc;
     margin-right: 12px;
     white-space: nowrap;
   }

   /* ── PRINT ── */
   @media print {
     body { background: white; color: #1a1a2e; }
